import{z as n,x as o,o as B,c as s,q as A,j as t,D as a,d as r,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"多资产执行","description":"","frontmatter":{"title":"多资产执行","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-multiasset.md","filePath":"quant/ex-multiasset.md","lastUpdated":1791413859000}'),p={name:"quant/ex-multiasset.md"};function d(C,E,u,D,h,_){const e=o("Mermaid");return B(),s("div",null,[E[2]||(E[2]=A('<h1 id="多资产执行" tabindex="-1">多资产执行 <a class="header-anchor" href="#多资产执行" aria-label="Permalink to &quot;多资产执行&quot;">​</a></h1><div class="epigraph"><p>篮子执行把速度问题变成同步问题：每条腿各自最优的轨迹加总，可以比一条次优但同步的轨迹贵得多。</p><footer>—— 据 Almgren and Chriss, Optimal Execution of Portfolio Transactions, Journal of Risk, 2000/2001 多资产扩展；指数再平衡与 ETF 实务整理</footer></div><p><a href="/quant/ex-vol-execution">上一课</a>把体制切换写进单标的算法；组合的世界里母单不是数而是向量：调仓篮子、对冲腿、货币腿与展期。主干各执行课都隐含「其他腿给定」，本课解开来：腿间怎么排程、怎么记账、风险怎么换形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合层给出目标向量 \\(\\Delta w\\)，执行层面对三重耦合。协方差耦合：余量风险是 \\(x_t^\\top \\Sigma x_t\\)，单标的日程不看相关性，组合方差被腿间错配放大。冲击耦合：冲击系数是矩阵 \\(\\eta_{ij}\\)，卖 A 的同时买同行业的 B，两条腿的冲击互写；对角近似在相关腿上算错。同步耦合：多腿策略（配对、指数套利、期现替换）的价值在价差上，一条腿先动，开放的是基差暴露而非单边暴露，见 <a href="/quant/index-arb">指数套利</a>。</p><p>第一句话是：哪些腿必须同时动、哪些可以先后动、先动哪条。这不是调度细节，是风险在价格、基差、冲击之间的分配决定。</p>',6)),(B(),t(l,null,{default:a(()=>[i(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E7%9B%AE%E6%A0%87%E5%90%91%E9%87%8F%20%CE%94w%22%5D%20--%3E%20C1%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%E8%80%A6%E5%90%88%EF%BC%9A%E4%BD%99%E9%87%8F%E9%A3%8E%E9%99%A9%20x'%CE%A3x%22%5D%0A%20%20T%20--%3E%20C2%5B%22%E5%86%B2%E5%87%BB%E8%80%A6%E5%90%88%EF%BC%9A%E5%86%B2%E5%87%BB%E7%B3%BB%E6%95%B0%E6%98%AF%E7%9F%A9%E9%98%B5%20%CE%B7_ij%22%5D%0A%20%20T%20--%3E%20C3%5B%22%E5%90%8C%E6%AD%A5%E8%80%A6%E5%90%88%EF%BC%9A%E7%AD%96%E7%95%A5%E4%BB%B7%E5%80%BC%E5%9C%A8%E4%BB%B7%E5%B7%AE%E4%B8%8A%22%5D%0A%20%20C1%20--%3E%20E1%5B%22%E5%8D%95%E8%85%BF%E6%97%A5%E7%A8%8B%E4%B8%8D%E7%9C%8B%E7%9B%B8%E5%85%B3%EF%BC%8C%E8%85%BF%E9%97%B4%E9%94%99%E9%85%8D%E6%94%BE%E5%A4%A7%E7%BB%84%E5%90%88%E6%96%B9%E5%B7%AE%22%5D%0A%20%20C2%20--%3E%20E2%5B%22%E5%90%8C%E8%A1%8C%E4%B8%9A%E4%B8%80%E4%B9%B0%E4%B8%80%E5%8D%96%EF%BC%8C%E4%B8%A4%E6%9D%A1%E8%85%BF%E7%9A%84%E5%86%B2%E5%87%BB%E4%BA%92%E5%86%99%22%5D%0A%20%20C3%20--%3E%20E3%5B%22%E4%B8%80%E6%9D%A1%E8%85%BF%E5%85%88%E5%8A%A8%EF%BC%8C%E5%BC%80%E6%94%BE%E7%9A%84%E6%98%AF%E5%9F%BA%E5%B7%AE%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20E1%20--%3E%20S%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9A%E5%85%88%E5%86%B3%E5%AE%9A%E5%93%AA%E4%BA%9B%E8%85%BF%E5%90%8C%E6%97%B6%E5%8A%A8%E3%80%81%E5%85%88%E5%90%8E%E4%B8%8E%E8%B0%81%E5%85%88%22%5D%0A%20%20E2%20--%3E%20S%0A%20%20E3%20--%3E%20S%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h3 id="领先腿与兑换" tabindex="-1">领先腿与兑换 <a class="header-anchor" href="#领先腿与兑换" aria-label="Permalink to &quot;领先腿与兑换&quot;">​</a></h3><p>流动性组合常用领先腿策略：先用流动性最好的工具（股指期货、ETF）拿到方向暴露，再把期货头寸逐步「兑换」成现金篮子。期货腿即时完成，付基差与展期成本，见 <a href="/quant/cn-index-basis-hedge-cost">股指期货基差与对冲成本</a>；现货篮子按日程摊开，付冲击。兑换节奏由基差与冲击的相对价格决定：基差偏离持有成本时放缓，冲击便宜时加快。ETF 申赎是另一条通道：用成分股篮子换份额，几百条腿的执行换成一次创建，代价是篮子清单、现金差额与费用。</p><p><span class="marginnote">同步约束应写成余量暴露的容忍带，而不是「腿必须同秒完成」：例如篮子剩余净暴露不超过目标的 \\(x\\%\\) 且存活不超过 \\(n\\) 分钟。带宽由基差波动与均值回复定，不由愿望定。</span></p><p><span class="marginnote">领先腿与兑换可以类比搬家：先租一个小仓库，当天把全部家具放进去（期货先拿方向暴露），之后一个月分批搬进新家（现货篮子摊开执行）。仓库费是基差与展期成本，搬运的折腾是冲击成本——租多久、搬多快，看两种费用的相对价格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态向量 \\(x_t\\)（各腿剩余库存）与组合层控制：每周期解一个小型多资产 AC——目标含 \\(x^\\top \\Sigma x\\) 与冲击项，约束含每腿参与率与篮子暴露带。工程上是分层：组合层管暴露带与兑换节奏（分钟到小时），单腿层沿用已写的调度与接口，两层用同一份 <a href="/quant/arrival-price">到达价</a> 会计。记账规则事先写死：对冲腿滑点记入<strong>组合缺口</strong>，不许藏进「股票腿执行得很好」；兑换中的基差损益单独列，见 <a href="/quant/slippage-attribution">滑点归因</a> 的科目表。</p><p>特殊腿：货币腿先轧差再执行残余；展期按 <a href="/quant/roll-volume-oi">展期成交量与持仓</a> 的集中度排程；借券受限的空头腿要先确认可得性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步策略的本质是风险的换形：把窗口内的价格波动风险换成基差风险。交换划不划算，取决于基差相对价格的波动与回复性——期货基差在到期前有锚，价格没有；所以期货做领先腿在多数再平衡窗口里占优。但对角化模型在两处机制性失效：相关矩阵在恐慌日向全 1 阵坍缩（两两相关性趋于 1，<a href="/quant/ex-vol-execution">波动执行的专门问题</a> 的同步性放大器在组合里更强），「分散化」是幻觉；冲击交叉项在内部化时可正可负，双向腿轧差的节省不该重复计费。</p><p>内生性同样存在：指数纳入日所有跟踪组合执行同一个篮子，对手曲线里有大量同向算法流；<a href="/quant/arrival-price">到达价格算法</a> 的拥挤警告在篮子层表现为：平静日校准的 \\(\\eta\\) 低估指数日冲击。</p><p><span class="marginnote">数字感受「风险的换形」：股指期货到期日被现金交割机制锚定，基差偏离持有成本后会收敛；股票价格没有锚。现货篮子要执行 30 分钟，期货领先腿在这 30 分钟里承担的是基差波动——通常远小于同窗口的价格波动。换腿不是为了快，是为了把不可控的价格风险换成有锚的基差风险。</span></p>',11)),(B(),t(l,null,{default:a(()=>[i(e,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%E5%90%91%E9%87%8F%20%CE%94w%22%5D%20--%3E%20LEAD%5B%22%E9%A2%86%E5%85%88%E8%85%BF%3A%20%E6%9C%9F%E8%B4%A7%20%2F%20ETF%22%5D%0A%20%20TGT%20--%3E%20BASK%5B%22%E7%8E%B0%E8%B4%A7%E7%AF%AE%E5%AD%90%E6%97%A5%E7%A8%8B%22%5D%0A%20%20LEAD%20--%3E%20BS%5B%22%E5%9F%BA%E5%B7%AE%E7%9B%91%E6%8E%A7%22%5D%0A%20%20BS%20--%3E%20CONV%7B%22%E5%85%91%E6%8D%A2%E8%8A%82%E5%A5%8F%22%7D%0A%20%20CONV%20--%3E%20BASK%0A%20%20BASK%20--%3E%20BAND%7B%22%E7%AF%AE%E5%AD%90%E6%9A%B4%E9%9C%B2%E5%B8%A6%22%7D%0A%20%20BAND%20--%3E%7C%E8%B6%8A%E5%B8%A6%7C%20REB%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E9%87%8D%E6%8E%92%E5%90%84%E8%85%BF%E9%85%8D%E9%A2%9D%22%5D%0A%20%20BAND%20--%3E%7C%E5%B8%A6%E5%86%85%7C%20KEEP%5B%22%E7%BB%A7%E7%BB%AD%E5%8D%95%E8%85%BF%E8%B0%83%E5%BA%A6%22%5D%0A%20%20REB%20--%3E%20BASK%0A%20%20FIL%5B%22%E5%90%84%E8%85%BF%E6%88%90%E4%BA%A4%22%5D%20--%3E%20ACC%5B%22%E7%BB%84%E5%90%88%E7%BC%BA%E5%8F%A3%E8%AE%B0%E8%B4%A6%3A%20%E8%85%BF%E6%BB%91%E7%82%B9%20%2B%20%E5%9F%BA%E5%B7%AE%20%2B%20%E5%86%B2%E5%87%BB%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交易时段与制度错位是硬边界：个股停牌而期货在动，基差带失去意义，剩余腿按新现实重排；T+1 约束当日买入不可回转，多空腿的现金与券源按 <a href="/quant/cn-tplus1">T+1 与回转交易约束</a> 预排；保证金占用约束期货腿规模。协方差与冲击矩阵都是估计量，样本外漂移快。评价上组合缺口是唯一加总口径：分腿跑赢各自的 VWAP 而篮子被价差打穿，TCA 必须显性报告为同步成本。</p><p><span class="marginnote">常见误区：各腿单独看 TCA 都「跑赢 VWAP」就认为执行成功。若股票腿与期货腿错开 20 分钟，篮子在错配窗口里吃进基差波动——分腿成绩单各自好看，组合缺口却劣化。加总口径只有组合缺口，同步成本必须显性列示。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多资产执行的三重耦合：协方差、冲击交叉项、腿间同步；单腿最优的加总不是组合最优。</li><li>领先腿—兑换结构把价格风险换成有锚的基差风险，节奏由基差与冲击的相对价格定。</li><li>同步约束写成暴露容忍带，带宽由基差波动定。</li><li>对冲腿滑点记入组合缺口；基差损益与冲击、时机分科目。</li><li>恐慌日协方差坍缩使对角模型失效；指数日对手曲线含同向流。</li><li>时段错位、T+1、保证金与借券可得性是硬约束，先于日程确认。</li><li>出处：Almgren and Chriss, <em>Journal of Risk</em>, 2000/2001；基差与对冲成本口径见股指期货章节；Perold 的实施缺口为记账基准。</li></ul>',5))])}const c=n(p,[["render",d]]);export{T as __pageData,c as default};
